function main({data1}){
    // 将隐藏的换行符显性展示出来
    const processedResult = data1.replace(/\n/g, '\\n')
                                .replace(/\r/g, '\\r')
                                .replace(/\t/g, '\\t');

    const result = {
        businessType: "consult",
        result: processedResult
    };

    return {
        result: result
    }
}

